"""Upper-triangular matmul: triu(A @ B) for upper-triangular square A, B."""
import jax
import jax.numpy as jnp

CONFIG = {'name': '14_Matmul_for_upper_triangular_matrices', 'N': 4096}


def create_inputs(dtype=jnp.float32):
    n = CONFIG['N']
    k1, k2 = jax.random.split(jax.random.key(0))
    A = jnp.triu(jax.random.uniform(k1, (n, n), dtype=dtype))
    B = jnp.triu(jax.random.uniform(k2, (n, n), dtype=dtype))
    return (A, B)


def workload(A, B):
    C = jnp.matmul(A, B, precision=jax.lax.Precision.HIGHEST)
    return jnp.triu(C)

"""Matrix-vector multiplication: C = A @ B with A (M, K), B (K, 1)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '4_Matrix_vector_multiplication_',
    'M': 1024,
    'K': 65536,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    ka, kb = jax.random.split(key)
    A = jax.random.uniform(ka, (CONFIG['M'], CONFIG['K']), dtype=dtype)
    B = jax.random.uniform(kb, (CONFIG['K'], 1), dtype=dtype)
    return A, B


def workload(A, B):
    return jnp.matmul(A, B, precision=jax.lax.Precision.HIGHEST)
